            for token in tokens:
                if token in self.vocab:
                    all_ids.append(_____)
                else:
                    all_ids.append(self.vocab.get("<unk>", -1))
        return all_ids

    def decode(self, ids):
        """将 token ID 列表解码为文本"""
        tokens = []
        for id_ in ids:
            # ===== 填空 7: ID 转 token =====
            token = _____
            tokens.append(token)

        text = ""
        for token in tokens:
            if token in self.special_tokens:
                text += token
            # ===== 填空 8: 处理 </w> 词尾标记 =====
            elif token.endswith("</w>"):
                text += _____ + " "
            else:
                text += token
        return text.strip()
